{
  "technical_and_design_decisions": [
    "Implement the new helpers in Go as part of the existing Hyperledger Fabric channel configuration library, reusing current protobuf types and ConfigUpdate computation utilities.",
    "For capability modifications (U5), provide explicit enable/disable toggle functions (e.g., EnableV20ApplicationCapabilities, DisableApplicationCapabilities) instead of arbitrary setters, to prevent unsupported capabilities from being set.",
    "For policy retrieval (U3), implement a single generic helper that locates an organization across application, orderer, and consortium groups and returns its policies without manual parsing by the caller.",
    "For orderer endpoint changes (U1/U2), modify the Endpoint value inside the target orderer organization's config group and rely on existing delta computation to produce a signed ConfigUpdate.",
    "For ACL modifications (U7), operate on the Application configuration's ACLs map via add/remove helpers that keep the config transaction ready for further updates.",
    "For example tests (U8), replace the single end-to-end example with multiple smaller Example functions grouped by domain (orderer, application, org management, MSP, capabilities) and demonstrate each new API within the relevant example."
  ],
  "assumptions": [
    "The existing library already supports loading a Config block/transaction and computing a ConfigUpdate, so only higher-level helpers are added.",
    "The developer is already familiar with Hyperledger Fabric config internals and Go tooling; no training or onboarding effort is included.",
    "Example tests refer to Go example_test.go functions executed by 'go test'; output comments will be updated as required.",
    "No changes to Fabric protobuf definitions, consensus, or membership services are needed for this increment.",
    "Effort includes local unit/example testing, debugging, and self-review, but excludes external review cycles, CI waiting time, and elapsed calendar duration.",
    "All new functions are added to the same Go package as the current config API and follow its established patterns."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Requirements analysis, design, and environment setup",
      "activity_description": "Review the user stories, decide API signatures and technical approach, set up the development branch, and build the existing library to establish a baseline.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement orderer endpoint add/remove (U1, U2)",
      "activity_description": "Implement functions to add and remove an orderer endpoint in an orderer org's config group, ensuring the modified config can be turned into a ConfigUpdate transaction ready for signatures.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Implement retrieve org policies (U3)",
      "activity_description": "Implement a helper that retrieves existing policies for a specified organization from application, orderer, or consortium groups without manual config parsing.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Implement retrieve capabilities (U4)",
      "activity_description": "Implement functions to retrieve orderer, application, and channel capabilities from a config transaction, returning config.Capabilities types.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement capability add/remove toggles (U5)",
      "activity_description": "Implement enable/disable toggle functions for application, orderer, and channel capabilities, modifying the config transaction while preventing unsupported capability values.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Implement retrieve application config (U6)",
      "activity_description": "Implement a helper that returns the application configuration (config.Application) from a config transaction.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Implement application ACL updates (U7)",
      "activity_description": "Implement functions to add and remove ACLs in an application group's configuration, keeping the config transaction ready for further updates.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Refactor example tests into focused examples (U8)",
      "activity_description": "Split the existing monolithic end-to-end example test into separate example function stubs covering orderer config, application values, org management, MSP, and capabilities.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Add example usages for new helpers (U1-U7)",
      "activity_description": "Populate the split example functions and add new example tests that demonstrate usage of the orderer endpoint, policies, capabilities, application config, and ACL helpers.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Comprehensive testing and defect fixing",
      "activity_description": "Execute the full unit and example test suite, verify ConfigUpdate transactions are correctly formed, and debug or fix any defects found.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Documentation and final verification",
      "activity_description": "Add godoc comments, run linters and final build, perform self-review, and prepare the changes for delivery.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 83
  }
}

